// Emits the EF Core model for the approved 58-table design from ../schema.json (generated by build.mjs from model.mjs).
// Run from this folder after build.mjs:  node emit-efcore.mjs
// Output (generated; do not hand-edit):
//   src/DeepSprout.Domain/V5/V5Entities.g.cs                       one POCO per table
//   src/DeepSprout.Infrastructure/V5/V5ModelConfiguration.g.cs     Fluent API: keys, columns, defaults, checks, FKs, indexes
//   src/DeepSprout.Infrastructure/V5/DeepSproutV5DbContext.Sets.g.cs  one DbSet per table
// Names follow emit-sql.mjs exactly (PK_, UQ_, UX_, IX_, FK_, CK_), so the EF model and the SQL script describe the same database.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const repo = path.resolve(here, '../../../../..');
// An optional argument emits from another schema.json (used once to build the v5-lean-1 migration baseline).
const schema = JSON.parse(fs.readFileSync(process.argv[2] || path.join(here, '..', 'schema.json'), 'utf8'));
const T = schema.tables;
const short = (full) => full.split('.')[1];
const schemaOf = (full) => full.split('.')[0];
const cs = (s) => JSON.stringify(s); // C# string literal (JSON escaping is valid C# for these contents)

// Check names exactly as emit-sql.mjs derives them (a clash inside one schema gets the table suffix).
const usedCk = new Map();
const ckName = (t, c) => {
  let n = c.name;
  const key = `${t.module}.${n}`;
  if (usedCk.has(key) && usedCk.get(key) !== t.table) n = `${n}_${short(t.table)}`;
  usedCk.set(`${t.module}.${n}`, t.table);
  return n;
};

function clrType(c) {
  const base = c.type.replace(/\(.*\)/, '').toLowerCase();
  const map = { bigint: 'long', int: 'int', smallint: 'short', tinyint: 'byte', bit: 'bool', decimal: 'decimal', datetime2: 'DateTime', date: 'DateOnly', uniqueidentifier: 'Guid', nvarchar: 'string', varchar: 'string', char: 'string', nchar: 'string', varbinary: 'byte[]', binary: 'byte[]', rowversion: 'byte[]' };
  const t = map[base];
  if (!t) throw new Error(`No CLR mapping for ${c.type}`);
  return t;
}
const isRef = (t) => t === 'string' || t === 'byte[]';

const header = '// <auto-generated>\n// Generated by docs/architecture/database/v5-lean-design/generator/emit-efcore.mjs from schema.json (v5 lean design, 58 tables).\n// Do not edit by hand: change generator/model.mjs, then run build.mjs, emit-sql.mjs and emit-efcore.mjs.\n// </auto-generated>\n#nullable enable\n';

// ── entities ──
let ent = header + '\nnamespace DeepSprout.Domain.V5;\n';
for (const t of T) {
  ent += `\n/// <summary>${t.table}: ${t.purpose.replace(/[<>&]/g, '')}</summary>\npublic sealed class ${short(t.table)}\n{\n`;
  for (const c of t.columns) {
    const ty = clrType(c);
    if (c.type === 'rowversion') { ent += `    public byte[] RowVersion { get; set; } = null!;\n`; continue; }
    if (c.nullable) ent += `    public ${ty}? ${c.name} { get; set; }\n`;
    else ent += `    public ${ty} ${c.name} { get; set; }${isRef(ty) ? ' = null!;' : ''}\n`;
  }
  ent += '}\n';
}

// ── configuration ──
let cfg = header + `using DeepSprout.Domain.V5;
using Microsoft.EntityFrameworkCore;

namespace DeepSprout.Infrastructure.V5;

internal static class V5ModelConfiguration
{
    public static void Apply(ModelBuilder m)
    {
`;
const tableNames = new Set(T.map((t) => t.table));
for (const t of T) {
  const n = short(t.table);
  const checks = [];
  for (const c of t.checks) checks.push([ckName(t, c), c.expression]);
  for (const c of t.columns) if (/Json$/.test(c.name) && c.type.startsWith('nvarchar')) checks.push([`CK_${n}_${c.name}_IsJson`, `${c.nullable ? `[${c.name}] IS NULL OR ` : ''}ISJSON([${c.name}]) = 1`]);
  cfg += `        m.Entity<${n}>(e =>\n        {\n`;
  cfg += `            e.ToTable(${cs(n)}, ${cs(schemaOf(t.table))}${checks.length ? ', t =>\n            {\n' + checks.map(([k, x]) => `                t.HasCheckConstraint(${cs(k)}, ${cs(x)});\n`).join('') + '            })' : ')'};\n`;
  cfg += `            e.HasKey(x => x.${t.primaryKey[0]}).HasName(${cs('PK_' + n)});\n`;
  for (const c of t.columns) {
    let p = `            e.Property(x => x.${c.name}).HasColumnType(${cs(c.type)})`;
    const len = c.type.match(/^(n?var(?:char|binary)|n?char|binary)\((\d+)\)$/i);
    if (len) p += `.HasMaxLength(${len[2]})`;
    if (/^(var)?char\(/i.test(c.type)) p += '.IsUnicode(false)';
    if (/^char\(/i.test(c.type)) p += '.IsFixedLength()';
    if (c.type === 'rowversion') p += '.IsRowVersion()';
    else if (c.default === 'IDENTITY(1,1)') p += '.UseIdentityColumn()';
    else if (c.default !== null && c.default !== undefined) p += `.HasDefaultValueSql(${cs(c.default)})`;
    if (!c.nullable && isRef(clrType(c)) && c.type !== 'rowversion') p += '.IsRequired()';
    cfg += p + ';\n';
  }
  // unique: plain UNIQUE constraints and filtered unique indexes, named as in the SQL script
  const leading = new Set();
  let k = 0;
  for (const u of t.unique) {
    leading.add(u.columns[0]);
    const cols = u.columns.length === 1 ? `x.${u.columns[0]}` : `new { ${u.columns.map((c) => 'x.' + c).join(', ')} }`;
    // Named indexes: the design has several indexes over the same columns (for example two filtered uniques on CycleId).
    // HasFilter(null) keeps a plain UNIQUE's SQL Server semantics (EF would otherwise add "IS NOT NULL" filters).
    if (u.filter) { k++; cfg += `            e.HasIndex(x => ${cols}, ${cs(`UX_${n}_${u.columns.join('_')}_${k}`)}).IsUnique().HasFilter(${cs(u.filter)});\n`; }
    else cfg += `            e.HasIndex(x => ${cols}, ${cs(`UQ_${n}_${u.columns.join('_')}`)}).IsUnique().HasFilter(null);\n`;
  }
  for (const i of t.indexes) {
    leading.add(i.columns[0]);
    const cols = i.columns.length === 1 ? `x.${i.columns[0]}` : `new { ${i.columns.map((c) => 'x.' + c).join(', ')} }`;
    cfg += `            e.HasIndex(x => ${cols}, ${cs(`IX_${n}_${i.columns.join('_')}`)})${i.filter ? `.HasFilter(${cs(i.filter)})` : ''};\n`;
  }
  for (const f of t.foreignKeys) {
    if (!tableNames.has(f.references)) throw new Error(`FK target missing ${f.references}`);
    if (!leading.has(f.column)) { leading.add(f.column); cfg += `            e.HasIndex(x => x.${f.column}, ${cs(`IX_${n}_${f.column}`)});\n`; }
    cfg += `            e.HasOne<${short(f.references)}>().WithMany().HasForeignKey(x => x.${f.column}).HasConstraintName(${cs(`FK_${n}_${f.column}`)}).OnDelete(DeleteBehavior.NoAction);\n`;
  }
  cfg += '        });\n';
}
cfg += '    }\n}\n';

// ── DbSets ──
let sets = header + `using DeepSprout.Domain.V5;
using Microsoft.EntityFrameworkCore;

namespace DeepSprout.Infrastructure.V5;

public sealed partial class DeepSproutV5DbContext
{
${T.map((t) => `    public DbSet<${short(t.table)}> ${short(t.table)} => Set<${short(t.table)}>();`).join('\n')}
}
`;

const write = (rel, text) => { const p = path.join(repo, rel); fs.mkdirSync(path.dirname(p), { recursive: true }); fs.writeFileSync(p, text.replace(/\r?\n/g, '\r\n'), 'utf8'); };
write('src/DeepSprout.Domain/V5/V5Entities.g.cs', ent);
write('src/DeepSprout.Infrastructure/V5/V5ModelConfiguration.g.cs', cfg);
write('src/DeepSprout.Infrastructure/V5/DeepSproutV5DbContext.Sets.g.cs', sets);
console.log(`EF model emitted: ${T.length} entities, ${T.reduce((n, t) => n + t.columns.length, 0)} columns, ${T.reduce((n, t) => n + t.foreignKeys.length, 0)} FKs (${schema.version || ''})`);
